import React, { useState, useEffect, useCallback, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import clsx from 'clsx';
import './AcidContextMenu.css';

export interface ContextMenuItem {
    label?: string;
    icon?: React.ReactNode;
    onClick?: () => void;
    destructive?: boolean;
    disabled?: boolean;
    divider?: boolean;
}

export interface AcidContextMenuProps {
    items: ContextMenuItem[];
    children: React.ReactNode;
    className?: string;
}

export const AcidContextMenu = ({
    items,
    children,
    className
}: AcidContextMenuProps) => {
    const [visible, setVisible] = useState(false);
    const [position, setPosition] = useState({ x: 0, y: 0 });
    const menuRef = useRef<HTMLDivElement>(null);

    const handleContextMenu = useCallback((e: React.MouseEvent) => {
        e.preventDefault();
        setPosition({ x: e.clientX, y: e.clientY });
        setVisible(true);
    }, []);

    const closeMenu = useCallback(() => {
        setVisible(false);
    }, []);

    useEffect(() => {
        const handleClickOutside = (e: MouseEvent) => {
            if (menuRef.current && !menuRef.current.contains(e.target as Node)) {
                closeMenu();
            }
        };

        if (visible) {
            window.addEventListener('click', handleClickOutside);
            window.addEventListener('scroll', closeMenu);
        }

        return () => {
            window.removeEventListener('click', handleClickOutside);
            window.removeEventListener('scroll', closeMenu);
        };
    }, [visible, closeMenu]);

    return (
        <div
            className={clsx('ac-context-menu-wrapper', className)}
            onContextMenu={handleContextMenu}
        >
            {children}

            <AnimatePresence>
                {visible && (
                    <motion.div
                        ref={menuRef}
                        initial={{ opacity: 0, scale: 0.95 }}
                        animate={{ opacity: 1, scale: 1 }}
                        exit={{ opacity: 0, scale: 0.95 }}
                        transition={{ duration: 0.1, ease: 'easeOut' }}
                        className="ac-context-menu"
                        style={{ top: position.y, left: position.x }}
                    >
                        <div className="ac-context-menu-inner">
                            {items.map((item, i) => {
                                if (item.divider) {
                                    return <div key={i} className="ac-context-menu-divider" />;
                                }

                                return (
                                    <button
                                        key={i}
                                        className={clsx(
                                            'ac-context-menu-item',
                                            item.destructive && 'ac-context-menu-item-destructive',
                                            item.disabled && 'ac-context-menu-item-disabled'
                                        )}
                                        onClick={() => {
                                            if (!item.disabled) {
                                                item.onClick?.();
                                                closeMenu();
                                            }
                                        }}
                                        disabled={item.disabled}
                                    >
                                        <div className="ac-context-menu-item-content">
                                            {item.icon && <span className="ac-context-menu-icon">{item.icon}</span>}
                                            <span className="ac-context-menu-label">{item.label}</span>
                                        </div>
                                    </button>
                                );
                            })}
                        </div>
                    </motion.div>
                )}
            </AnimatePresence>
        </div>
    );
};

.ac-context-menu-wrapper {
    display: contents;
}

.ac-context-menu {
    position: fixed;
    z-index: 9999;
    min-width: 180px;
    background: var(--ac-bg);
    border: 1px solid var(--ac-border-active);
    box-shadow: 0 10px 25px -5px rgba(0, 0, 0, 0.5), 0 0 10px rgba(0, 0, 0, 0.3);
    padding: 4px;
    pointer-events: auto;
}

.ac-context-menu-inner {
    display: flex;
    flex-direction: column;
}

.ac-context-menu-item {
    width: 100%;
    display: flex;
    align-items: center;
    padding: 8px 10px;
    background: transparent;
    border: none;
    cursor: pointer;
    transition: background 0.15s, color 0.15s;
    border-radius: 2px;
}

.ac-context-menu-item:hover:not(.ac-context-menu-item-disabled) {
    background: rgba(var(--ac-brand-rgb), 0.1);
}

.ac-context-menu-item-content {
    display: flex;
    align-items: center;
    gap: 10px;
    width: 100%;
}

.ac-context-menu-icon {
    display: flex;
    align-items: center;
    justify-content: center;
    color: var(--ac-text-muted);
}

.ac-context-menu-label {
    font-size: 0.75rem;
    font-family: var(--font-mono);
    font-weight: 500;
    color: var(--ac-text);
    white-space: nowrap;
}

.ac-context-menu-item:hover .ac-context-menu-label {
    color: var(--ac-brand);
}

.ac-context-menu-item-destructive {
    color: #ff4d4d !important;
}

.ac-context-menu-item-destructive:hover:not(.ac-context-menu-item-disabled) {
    background: rgba(255, 77, 77, 0.1) !important;
}

.ac-context-menu-item-destructive .ac-context-menu-label {
    color: inherit;
}

.ac-context-menu-item-disabled {
    opacity: 0.4;
    cursor: not-allowed;
}

.ac-context-menu-divider {
    height: 1px;
    background: var(--ac-border-muted);
    margin: 4px;
}
